134	/**
135	 * Takes the person's statement: records their due-total now, binds each of their claims that counts to its
136	 * due as shown now (the greater of the floor in force on its date and its figure plus any late charge on it; a due already
137	 * bound stays as it is), and unbinds (live again) each that does not. While bound, a claim shows and totals that due: its
138	 * late charge no longer follows the sheet's today. The due-total is their counting claims' dues added up, at most the cap
139	 * in force on the sheet's today; n/a when their grade on the sheet's today has no rate there and no counting claim has a figure (kept, or at the
140	 * rate for the grade in force on its date).
141	 * <p>
142	 * Taken as of a date (on or before the sheet's today), it works on the sheet as it stood at the end of that date — every
143	 * change made while the sheet's today was on or before it, none made later — with that date standing in for the
144	 * sheet's today: it binds the person's claims that counted then to their figures then, unbinds every other claim of
145	 * theirs, and records that day's due-total and that date. Refused (400) for a date after the sheet's today, or one
146	 * when the person was not yet on the sheet.
147	 */
148	public class TakeStatement {
149	    public void take(@Val Person person, @Val StatementAsOf asOf, ClaimRepository claims, PersonRepository people,
150	            RateRepository rates, SheetRepository sheets, SettingRepository settings, SheetDayRepository days,
151	            Out<Statement> statement, Out<Person> updated) throws InvalidStatementException {
152	        LocalDate today = sheets.today(person.sheetId());
153	        LocalDate on = asOf.date() == null ? today : asOf.date();
154	        if (on.isAfter(today)) {
155	            throw new InvalidStatementException("A statement cannot be taken as of a date after the sheet's today.");
156	        }
157	        List<Claim> personClaims = claims.findForPerson(person.sheetId(), person.id());
158	        SheetState then = asOf.date() == null ? null : days.asOf(person.sheetId(), on);
159	        Person thenPerson = person;
160	        List<Claim> thenClaims = personClaims;
161	        List<Rate> sheetRates;
162	        DatedSettings dated;
163	        LocalDate policyDate;
164	        if (then == null) {
165	            sheetRates = rates.findAll(person.sheetId());
166	            dated = settings.dated(person.sheetId());
167	            policyDate = settings.policyDate(person.sheetId());
168	        } else {
169	            thenPerson = then.person(person.id());
170	            if (thenPerson == null) {
171	                throw new InvalidStatementException(person.name() + " was not on the sheet on " + on + ".");
172	            }
173	            thenClaims = then.claimsOf(person.id());
174	            sheetRates = then.rates();
175	            dated = then.dated();
176	            policyDate = then.policyDate();
177	        }
178	        Rounding rounding = Rounding.of(policyDate == null ? on : policyDate, dated::roundingModeOn, thenClaims);
179	        BigDecimal total = BigDecimal.ZERO.setScale(2);
180	        boolean kept = false;
181	        int counted = 0;
182	        Map<Long, BigDecimal> figures = new HashMap<>();
183	        for (Claim claim : thenClaims) {
184	            if (!thenPerson.counts(claim, on)) {
185	                continue;
186	            }
187	            boolean fixed = claim.keepsFigure();
188	            BigDecimal rate = Rate.inForce(sheetRates, thenPerson.gradeOn(claim.date()), claim);
189	            BigDecimal figure = claim.figure(rate, rounding);
190	            BigDecimal due = figure == null ? null
191	                    : claim.due(rate, dated.floorOn(claim.date()), dated.lateCharge(on, thenPerson), rounding);
192	            figures.put(claim.id(), due);
193	            counted++;
194	            kept |= fixed || figure != null;
195	            if (due != null) {
196	                total = total.add(due);
197	            }
198	        }
199	        for (Claim claim : personClaims) {
200	            boolean stated = figures.containsKey(claim.id());
201	            claims.bindStatement(claim, stated, stated ? figures.get(claim.id()) : null);
202	        }
203	        String dueTotal = Rate.inForce(sheetRates, thenPerson.gradeOn(on), on) == null && !kept ? "n/a"
204	                : Cap.apply(dated.capOn(on), total).setScale(2).toPlainString();
205	        statement.set(new Statement(person.name(), dueTotal, counted, asOf.date()));
206	        updated.set(people.recordStatement(person, dueTotal, on));
207	    }
208	}
