217	/** Refuses (400) a statement whose as-of date is not yyyy-mm-dd; a blank one takes the statement now. */
218	public class ValidateStatementRequest {
219	    public void validate(@RequestBody @Valid StatementRequest request, Out<StatementAsOf> asOf)
220	            throws InvalidStatementException {
221	        String value = request == null || request.asof() == null ? "" : request.asof().trim();
222	        if (value.isEmpty()) {
223	            asOf.set(new StatementAsOf(null));
224	            return;
225	        }
226	        try {
227	            asOf.set(new StatementAsOf(LocalDate.parse(value)));
228	        } catch (DateTimeParseException e) {
229	            throw new InvalidStatementException("A statement's date must be yyyy-mm-dd.");
230	        }
231	    }
232	}

