75	    /**
76	     * Insert a new person (null id) or update an existing one, bumping its version and storing its grades as
77	     * the person carries them; the person as stored, or null when the stored version is no longer the one the
78	     * person was loaded at. A new person's grade is recorded from the beginning of time.
79	     */
80	    public Person save(Person person) {
81	        if (person.id() != null) {
82	            int n = jdbc.update(
83	                    "UPDATE person SET name = ?, terms = ?, contact = ?, version = version + 1 WHERE id = ? AND sheet_id = ? AND version = ?",
84	                    person.name(), person.firstTerms(), person.contact(), person.id(), person.sheetId(), person.version());
85	            if (n == 0) {
86	                return null;
87	            }
88	            jdbc.update("DELETE FROM person_grade WHERE person_id = ? AND sheet_id = ?", person.id(), person.sheetId());
89	            for (GradeFrom g : person.grades()) {
90	                insertGrade(person.sheetId(), person.id(), g);
91	            }
92	            insertTerms(person.sheetId(), person.id(), person.termsFrom());
93	            return new Person(person.id(), person.sheetId(), person.name(), person.grade(), person.version() + 1,
94	                    person.statementCount(), person.statedTotal(), person.statementDate(), person.retiredFrom(),
95	                    person.holds(), person.grades(), person.terms(), person.contact(), person.pastRetirements(),
96	                    person.termsFrom());
97	        }
98	        GeneratedKeyHolder keys = new GeneratedKeyHolder();
99	        jdbc.update(con -> {
100	            PreparedStatement ps = con.prepareStatement(
101	                    "INSERT INTO person (sheet_id, name, grade, terms, contact, position) VALUES (?, ?, ?, ?, ?, "
102	                            + NEXT_POSITION + ")", new String[] { "id" });
103	            ps.setString(1, person.sheetId());
104	            ps.setString(2, person.name());
105	            ps.setString(3, person.grade());
106	            ps.setObject(4, person.firstTerms());
107	            ps.setString(5, person.contact());
108	            ps.setString(6, person.sheetId());
109	            return ps;
110	        }, keys);
111	        long id = keys.getKey().longValue();
112	        insertGrade(person.sheetId(), id, new GradeFrom(person.grade(), null));
113	        insertTerms(person.sheetId(), id, person.termsFrom());
114	        return new Person(id, person.sheetId(), person.name(), person.grade(), 0, 0, null, null, null, List.of(),
115	                person.grades(), person.terms(), person.contact(), List.of(), person.termsFrom());
116	    }
