120	        jdbc.update("DELETE FROM person_terms WHERE person_id = ? AND sheet_id = ?", personId, sheetId);
121	        for (TermsFrom t : terms) {
122	            if (t.from() != null) {
123	                jdbc.update("INSERT INTO person_terms (sheet_id, person_id, terms, from_date) VALUES (?, ?, ?, ?)",
124	                        sheetId, personId, t.terms(), Date.valueOf(t.from()));
125	            }
126	        }
