129	    private void insertGrade(String sheetId, long personId, GradeFrom grade) {
130	        jdbc.update("INSERT INTO person_grade (sheet_id, person_id, grade, from_date) VALUES (?, ?, ?, ?)", sheetId,
131	                personId, grade.grade(), grade.from() == null ? null : Date.valueOf(grade.from()));
