134	    /**
135	     * The people with the grades, holds and past retirements recorded for them, each showing the grade in force on
136	     * the sheet's today; their holds and past retirements oldest first.
137	     */
138	    private List<Person> withGrades(String sheetId, List<Person> found) {
139	        if (found.isEmpty()) {
140	            return found;
141	        }
142	        Map<Long, List<GradeFrom>> grades = new HashMap<>();
143	        jdbc.query("SELECT person_id, grade, from_date FROM person_grade WHERE sheet_id = ?", (rs) -> {
144	            grades.computeIfAbsent(rs.getLong("person_id"), (k) -> new ArrayList<>())
145	                    .add(new GradeFrom(rs.getString("grade"), rs.getObject("from_date", LocalDate.class)));
146	        }, sheetId);
147	        Map<Long, List<TermsFrom>> terms = new HashMap<>();
148	        jdbc.query("SELECT person_id, terms, from_date FROM person_terms WHERE sheet_id = ? ORDER BY from_date", (rs) -> {
149	            terms.computeIfAbsent(rs.getLong("person_id"), (k) -> new ArrayList<>())
150	                    .add(new TermsFrom(rs.getObject("terms", Integer.class), rs.getObject("from_date", LocalDate.class)));
151	        }, sheetId);
152	        Map<Long, List<Hold>> holds = new HashMap<>();
153	        jdbc.query("SELECT person_id, from_date, to_date FROM person_hold WHERE sheet_id = ? ORDER BY id", (rs) -> {
154	            holds.computeIfAbsent(rs.getLong("person_id"), (k) -> new ArrayList<>()).add(new Hold(
155	                    rs.getObject("from_date", LocalDate.class), rs.getObject("to_date", LocalDate.class)));
156	        }, sheetId);
157	        Map<Long, List<PastRetirement>> retirements = new HashMap<>();
158	        jdbc.query("SELECT person_id, from_date, to_date FROM person_retirement WHERE sheet_id = ? ORDER BY id", (rs) -> {
159	            retirements.computeIfAbsent(rs.getLong("person_id"), (k) -> new ArrayList<>()).add(new PastRetirement(
160	                    rs.getObject("from_date", LocalDate.class), rs.getObject("to_date", LocalDate.class)));
161	        }, sheetId);
162	        List<LocalDate> today = jdbc.query("SELECT today FROM sheet WHERE id = ?",
163	                (rs, n) -> rs.getObject("today", LocalDate.class), sheetId);
164	        LocalDate on = today.isEmpty() ? LocalDate.now() : today.get(0);
165	        List<Person> people = new ArrayList<>();
166	        for (Person p : found) {
167	            List<GradeFrom> own = grades.getOrDefault(p.id(), List.of(new GradeFrom(p.grade(), null)));
168	            List<TermsFrom> ownTerms = new ArrayList<>();
169	            ownTerms.add(new TermsFrom(p.terms(), null));
170	            ownTerms.addAll(terms.getOrDefault(p.id(), List.of()));
171	            people.add(new Person(p.id(), p.sheetId(), p.name(), Person.gradeOn(own, on, p.grade()), p.version(),
172	                    p.statementCount(), p.statedTotal(), p.statementDate(), p.retiredFrom(),
173	                    List.copyOf(holds.getOrDefault(p.id(), List.of())), List.copyOf(own),
174	                    Person.ownTermsOn(ownTerms, on), p.contact(),
175	                    List.copyOf(retirements.getOrDefault(p.id(), List.of())), List.copyOf(ownTerms)));
176	        }
177	        return people;
178	    }
