262	    /**
263	     * Merge the person ({@code from}, their claims already moved) into the other: their name and then their aliases,
264	     * in the order added, become the other's newest aliases; their patrons are added after the other's, in the order named (not the other,
265	     * no repeats); anyone naming them as patron names the other instead (not themselves, no repeats); their pool
266	     * and crew memberships, crews they lead, and plans move to the other (shares added where the other is already a member). Their statements join
267	     * the other's, before them: the other's count is both counts added, and the other's last statement stays theirs (or,
268	     * having none, becomes the merged person's). Their grades,
269	     * holds, past retirements, watchers, snapshot lines and contact are dropped with them.
270	     */
271	    public void merge(Person from, Person into) {
272	        String sheetId = from.sheetId();
273	        long gone = from.id();
274	        long kept = into.id();
275	        List<String> aliases = jdbc.queryForList(
276	                "SELECT alias FROM person_alias WHERE sheet_id = ? AND person_id = ? ORDER BY id", String.class,
277	                sheetId, gone);
278	        jdbc.update("DELETE FROM person_alias WHERE sheet_id = ? AND person_id = ?", sheetId, gone);
279	        List<String> added = new ArrayList<>();
280	        added.add(from.name());
281	        added.addAll(aliases);
282	        for (String alias : added) {
283	            jdbc.update("INSERT INTO person_alias (sheet_id, person_id, alias) VALUES (?, ?, ?)", sheetId, kept, alias);
284	        }
285	
286	        jdbc.update("INSERT INTO person_patron (sheet_id, person_id, patron_id) SELECT sheet_id, ?, patron_id"
287	                + " FROM person_patron p WHERE sheet_id = ? AND person_id = ? AND patron_id <> ? AND NOT EXISTS"
288	                + " (SELECT 1 FROM person_patron q WHERE q.person_id = ? AND q.patron_id = p.patron_id) ORDER BY seq",
