324	    /**
325	     * Swap the person with the one above (up) or below (down) them in the sheet's list; their new position, counting
326	     * from 1, or 0 when there is no one there (the top person moving up, the bottom one down).
327	     */
328	    public int move(Person person, boolean up) {
329	        List<Map<String, Object>> order = jdbc.queryForList(
330	                "SELECT id, position FROM person WHERE sheet_id = ? ORDER BY position, id", person.sheetId());
331	        int at = -1;
332	        for (int i = 0; i < order.size(); i++) {
333	            if (((Number) order.get(i).get("id")).longValue() == person.id()) {
334	                at = i;
335	            }
336	        }
337	        int to = up ? at - 1 : at + 1;
338	        if (at < 0 || to < 0 || to >= order.size()) {
339	            return 0;
340	        }
341	        // the list renumbered 1..n with the two swapped, so no two people ever share a position
342	        for (int i = 0; i < order.size(); i++) {
343	            long position = i == at ? to + 1 : i == to ? at + 1 : i + 1;
344	            jdbc.update("UPDATE person SET position = ? WHERE id = ? AND sheet_id = ?", position,
345	                    order.get(i).get("id"), person.sheetId());
346	        }
347	        return to + 1;
348	    }
