449	     * counts added, and their last statement stays theirs (or, having none, becomes the gone person's).
450	     */
451	    private void mergeStatements(String sheetId, long gone, long kept) {
452	        int goneCount = jdbc.queryForObject("SELECT statement_count FROM person WHERE sheet_id = ? AND id = ?",
453	                Integer.class, sheetId, gone);
454	        if (goneCount > 0) {
455	            // shifted through negatives so no two statements of the kept person share a seq on the way
456	            jdbc.update("UPDATE person_statement SET seq = -(seq + ?) WHERE sheet_id = ? AND person_id = ?", goneCount,
457	                    sheetId, kept);
458	            jdbc.update("UPDATE person_statement SET seq = -seq WHERE sheet_id = ? AND person_id = ?", sheetId, kept);
459	            jdbc.update("UPDATE person_statement SET person_id = ? WHERE sheet_id = ? AND person_id = ?", kept, sheetId,
460	                    gone);
461	            jdbc.update("UPDATE person k SET stated_total = (SELECT g.stated_total FROM person g WHERE g.id = ?),"
462	                    + " statement_date = (SELECT g.statement_date FROM person g WHERE g.id = ?)"
463	                    + " WHERE k.sheet_id = ? AND k.id = ? AND k.statement_count = 0", gone, gone, sheetId, kept);
464	            jdbc.update("UPDATE person SET statement_count = statement_count + ? WHERE sheet_id = ? AND id = ?",
465	                    goneCount, sheetId, kept);
466	        }
