     3	/** The ids of the claims ticked for a bulk action, kept in the URL as a comma list under `claims`. */
     4	export function useSelectedClaims(): [Set<number>, (id: number, on: boolean) => void, () => void] {
     5	  const search = useSearch({ strict: false }) as Record<string, unknown>;
     6	  const navigate = useNavigate();
     7	  const selected = parse(search.claims);
     8	
     9	  // Each change is applied to the URL as it is then, so ticks in quick succession never clobber each other.
    10	  const update = (change: (ids: Set<number>) => void) => {
    11	    void navigate({
    12	      to: '.',
    13	      search: (prev: Record<string, unknown>) => {
    14	        const ids = parse(prev.claims);
    15	        change(ids);
    16	        const next = { ...prev };
    17	        if (ids.size === 0) delete next.claims;
    18	        else next.claims = [...ids].join(',');
    19	        return next;
    20	      },
    21	      replace: true,
    22	    });
    23	  };
    24	
    25	  const set = (id: number, on: boolean) => update((ids) => (on ? ids.add(id) : ids.delete(id)));
    26	  const clear = () => update((ids) => ids.clear());
    27	  return [selected, set, clear];
    28	}
