     3	
     4	// One error per claim row, shared by every action on the row (a status change, a move, the edit button, ...): the
     5	// row shows it once, and the next action on the row clears it.
     6	const errors = new Map<string, string>();
     7	const listeners = new Set<() => void>();
     8	
     9	function subscribe(listener: () => void) {
    10	  listeners.add(listener);
    11	  return () => listeners.delete(listener);
    12	}
    13	
    14	/** The claim row's error ('' when none) and the setter every action on the row uses. */
    15	export function useClaimError(claimId: number): [string, (message: string) => void] {
    16	  const [sheet] = useCurrentSheet();
    17	  const key = `${sheet}:${claimId}`;
    18	  const error = useSyncExternalStore(subscribe, () => errors.get(key) ?? '');
    19	  return [error, (message: string) => setClaimError(sheet, claimId, message)];
    20	}
    21	
    22	/** Set (or, with '', clear) the error of a claim row on the sheet. */
    23	export function setClaimError(sheet: string, claimId: number, message: string) {
    24	  const key = `${sheet}:${claimId}`;
    25	  if (message) errors.set(key, message);
    26	  else errors.delete(key);
    27	  listeners.forEach((l) => l());
    28	}

