     9	export type AgeBucket = '0-30' | '31-60' | '61';
    10	
    11	/** A claim's age on the sheet's today, in days from its date; a claim dated after today is 0. */
    12	export function claimAge(claim: Claim, today: string): number {
    13	  if (today === '' || claim.date >= today) return 0;
    14	  return Math.round((Date.parse(`${today}T00:00:00Z`) - Date.parse(`${claim.date}T00:00:00Z`)) / 86_400_000);
    15	}
    16	
    17	/** The bucket a claim's age falls in. */
    18	export function ageBucket(claim: Claim, today: string): AgeBucket {
    19	  const age = claimAge(claim, today);
    20	  return age <= 30 ? '0-30' : age <= 60 ? '31-60' : '61';
    21	}
    22	
    23	/**
    24	 * A person's OPEN and PENDING claims that count, their dues (late charges included) added up per age
    25	 * bucket (skipping n/a; 0.00 with none).
