    27	export function personAged(
    28	  claims: Claim[],
    29	  rates: Rate[],
    30	  grades: GradeFrom[],
    31	  holds: Hold[],
    32	  rules: DueRules,
    33	): Record<AgeBucket, string> {
    34	  const live = claims.filter((c) => isOpen(c) && counts(c, holds, rules.today));
    35	  const sum = (bucket: AgeBucket) =>
    36	    total(live.filter((c) => ageBucket(c, rules.today) === bucket).map((c) => claimDue(c, rates, grades, rules)));
