     6	/**
     7	 * The lines that follow a change's own records: one ROLLUP line per person whose figures it moved (a person new to the
     8	 * sheet counts as moved), in the order of the list, then a TOTALS line when the sheet's totals moved, then one ALERT
     9	 * line per person whose due-total went from at or below the sheet's alert threshold (or no due-total) to above it, in the
    10	 * order of the list.
    11	 */
    12	public final class RollupLines {
    13	
    14	    private RollupLines() {
    15	    }
    16	
    17	    /** Records the ROLLUP and TOTALS lines for the sheet's figures moving from {@code was} to {@code now}. */
    18	    public static void record(Rollup was, Rollup now, String sheetId, String user, Audit audit) {
    19	        String prefix = " sheet=" + sheetId + " by=" + user;
    20	        for (Map.Entry<Long, Rollup.Figures> entry : now.people().entrySet()) {
    21	            Rollup.Figures figures = entry.getValue();
    22	            if (!figures.sameAs(was.people().get(entry.getKey()))) {
    23	                audit.record("ROLLUP" + prefix + " person=" + figures.name() + " claimed=" + figures.claimed()
    24	                        + " due-total=" + figures.dueTotal() + " overdue-total=" + figures.overdueTotal());
    25	            }
    26	        }
    27	        if (!now.claimedTotal().equals(was.claimedTotal()) || !now.dueTotal().equals(was.dueTotal())
    28	                || !now.overdueTotal().equals(was.overdueTotal())) {
    29	            audit.record("TOTALS" + prefix + " claimed-total=" + now.claimedTotal() + " due-total="
    30	                    + now.dueTotal() + " overdue-total=" + now.overdueTotal());
    31	        }
    32	        for (Map.Entry<Long, Rollup.Figures> entry : now.people().entrySet()) {
    33	            Rollup.Figures figures = entry.getValue();
    34	            Rollup.Figures before = was.people().get(entry.getKey());
    35	            if (Rollup.above(figures.dueTotal(), now.alertThreshold())
    36	                    && !Rollup.above(before == null ? null : before.dueTotal(), now.alertThreshold())) {
    37	                audit.record("ALERT" + prefix + " name=" + figures.name() + " due-total=" + figures.dueTotal());
    38	            }
    39	        }
    40	    }
    41	}
