     8	/**
     9	 * Whether a claim is late in review: it is REVIEW, and its review day (the sheet's today when it last went to REVIEW,
    10	 * from its status log) plus the review SLA (whole days; '': none, never late) is before the sheet's today.
    11	 */
    12	export function reviewLate(claim: Claim, sla: string, today: string): boolean {
