    14	    private static final Set<String> GRADES = Set.of("A", "B", "C");
    15	
    16	    /** 0.00 or more, with at most two decimals. */
    17	    private static final Pattern PERCENT = Pattern.compile("\\d{1,5}(\\.\\d{1,2})?|\\.\\d{1,2}");
    18	
    19	    public void validate(@RequestBody @Valid RateRequest request, Out<RateRequest> body) throws InvalidRateException {
    20	        String grade = request.grade() == null ? "" : request.grade().trim().toUpperCase();
    21	        if (!GRADES.contains(grade)) {
    22	            throw new InvalidRateException("The grade must be A, B or C.");
    23	        }
    24	        String rate = request.rate() == null ? "" : request.rate().trim();
    25	        if (rate.isEmpty()) {
    26	            throw new InvalidRateException("A rate is required.");
    27	        }
    28	        if (!PERCENT.matcher(rate).matches()) {
    29	            throw new InvalidRateException("The rate must be a percent of 0.00 or more, with at most two decimals.");
    30	        }
    31	        String from = request.from() == null ? "" : request.from().trim();
    32	        if (!from.isEmpty()) {
    33	            try {
    34	                from = LocalDate.parse(from).toString();
    35	            } catch (DateTimeParseException e) {
    36	                throw new InvalidRateException("The from-date must be yyyy-mm-dd.");
    37	            }
    38	        }
    39	        String to = request.to() == null ? "" : request.to().trim();
    40	        if (!to.isEmpty()) {
    41	            try {
    42	                to = LocalDate.parse(to).toString();
    43	            } catch (DateTimeParseException e) {
    44	                throw new InvalidRateException("The to-date must be yyyy-mm-dd.");
    45	            }
    46	            if (!from.isEmpty() && to.compareTo(from) < 0) {
    47	                throw new InvalidRateException("The to-date must not be before the from-date.");
    48	            }
    49	        }
    50	        body.set(new RateRequest(grade, new BigDecimal(rate).setScale(2).toPlainString(), from.isEmpty() ? null : from,
    51	                to.isEmpty() ? null : to));
    52	    }
