    14	
    15	/** The person row's error of this kind ('' when none) and the setter every action on the row uses. */
    16	export function usePersonError(personId: number, kind = ''): [string, (message: string) => void] {
    17	  const [sheet] = useCurrentSheet();
    18	  const row = `${sheet}:${personId}`;
    19	  const key = kind ? `${row}:${kind}` : row;
    20	  const error = useSyncExternalStore(subscribe, () => errors.get(key) ?? '');
    21	  const setError = (message: string) => setPersonError(sheet, personId, message, kind);
    22	  return [error, setError];
    23	}
    24	
    25	/** Set (or, with '', clear) a person row's error from outside the row, as a bulk action does. */
    26	export function setPersonError(sheet: string, personId: number, message: string, kind = '') {
