    28	  const key = kind ? `${row}:${kind}` : row;
    29	  for (const k of [...errors.keys()]) {
    30	    if (k === row || k.startsWith(`${row}:`)) errors.delete(k);
    31	  }
    32	  if (message) errors.set(key, message);
    33	  listeners.forEach((l) => l());
    34	}
