156	    /** The ids of the sheet's descendants (children, their children, ...), by id; none when it has none. */
157	    public List<String> descendants(String sheetId) {
158	        java.util.Set<String> found = new java.util.TreeSet<>();
159	        java.util.Deque<String> todo = new java.util.ArrayDeque<>(List.of(sheetId));
160	        while (!todo.isEmpty()) {
161	            for (String child : jdbc.query("SELECT id FROM sheet WHERE parent_id = ?", (rs, n) -> rs.getString("id"),
162	                    todo.pop())) {
163	                if (!child.equals(sheetId) && found.add(child)) {
164	                    todo.push(child);
165	                }
166	            }
167	        }
168	        return List.copyOf(found);
169	    }
