     1	import type { Claim } from '../claims/claims';
     2	
     3	/** A duplicate: a person's claims on one date for one amount, counted. */
     4	export type Dup = { name: string; date: string; amount: string; count: number };
     5	
     6	/**
     7	 * The duplicate claims: for each person, date and amount with two or more claims (VOID and DELETED ones left out),
     8	 * people in list order, then by date, then by amount.
     9	 */
    10	export function duplicates(people: { id: number; name: string }[], claims: Claim[]): Dup[] {
    11	  const out: Dup[] = [];
    12	  for (const p of people) {
    13	    const groups = new Map<string, Dup>();
    14	    for (const c of claims) {
    15	      if (c.personId !== p.id || c.status === 'VOID' || c.status === 'DELETED') continue;
    16	      const key = `${c.date}|${c.amount}`;
    17	      const g = groups.get(key) ?? { name: p.name, date: c.date, amount: c.amount, count: 0 };
    18	      g.count++;
    19	      groups.set(key, g);
    20	    }
    21	    const dups = [...groups.values()].filter((g) => g.count >= 2);
    22	    dups.sort((a, b) => (a.date < b.date ? -1 : a.date > b.date ? 1 : Number(a.amount) - Number(b.amount)));
    23	    out.push(...dups);
    24	  }
    25	  return out;
    26	}
