    14	  const [error, setError] = useState('');
    15	  const queryClient = useQueryClient();
    16	  const once = useOneAtATime();
    17	  // The current id shows once everything kept for the sheet has been read, so what is on screen
    18	  // under it is what the store holds for that sheet. Checked after the screen's queries have
    19	  // mounted and started, so a query not yet begun does not count as read. Only a load (or a switch
    20	  // of sheet) hides it; a re-read some other change starts (a new today, a saved row) leaves the
    21	  // loaded sheet's id showing.
    22	  const fetching = useIsFetching({ queryKey: sheetKey(sheet) });
    23	  const [shown, setShown] = useState('');
    24	  const [loads, setLoads] = useState(0);
    25	  useEffect(() => {
    26	    setShown('');
    27	  }, [sheet, loads]);
    28	  useEffect(() => {
    29	    if (fetching > 0) return;
    30	    const timer = setTimeout(() => {
    31	      const queries = queryClient.getQueryCache().findAll({ queryKey: sheetKey(sheet) });
    32	      if (queries.every((q) => q.state.fetchStatus === 'idle' && q.state.status !== 'pending')) setShown(sheet);
    33	    }, 0);
    34	    return () => clearTimeout(timer);
    35	  }, [sheet, loads, fetching, queryClient]);
    36	
    37	  const load = useMutation({
    38	    mutationFn: (sheetId: string) => postJson<{ id: string }>('/api/sheets', { id: sheetId }),
    39	    onSuccess: async ({ id: loaded }) => {
    40	      setSheet(loaded);
    41	      setLoads((n) => n + 1);
    42	      await queryClient.invalidateQueries({ queryKey: sheetKey(loaded) });
    43	    },
    44	    onError: () => setError('That sheet could not be loaded.'),
    45	  });
