    11	/**
    12	 * A sheet's permission matrix: for each action set, the roles allowed it, as typed and shown (comma separated role
    13	 * labels). An action not set keeps the standing rule: open, settle, void and close by clerk and steward; reassign and
    14	 * reopen by steward. Not dated.
    15	 */
    16	public record Permissions(Map<String, String> set) {
    17	
    18	    public static final String OPEN = "open";
    19	    public static final String SETTLE = "settle";
    20	    public static final String VOID = "void";
    21	    public static final String REASSIGN = "reassign";
    22	    public static final String CLOSE = "close";
    23	    public static final String REOPEN = "reopen";
    24	
    25	    /** The actions the matrix covers, in the order they are shown and recorded. */
    26	    public static final List<String> ACTIONS = List.of(OPEN, SETTLE, VOID, REASSIGN, CLOSE, REOPEN);
    27	
    28	    /** The setting key of an action's entry: perm-&lt;action&gt;. */
    29	    public static String key(String action) {
    30	        return "perm-" + action;
    31	    }
    32	
    33	    /** The roles allowed the action when none are set. */
    34	    private static Set<Role> standing(String action) {
    35	        return switch (action) {
    36	            case REASSIGN, REOPEN -> EnumSet.of(Role.STEWARD);
    37	            default -> EnumSet.of(Role.CLERK, Role.STEWARD);
    38	        };
    39	    }
    40	
    41	    /** The roles in a comma separated list as typed (each case and outer spaces ignored), or null when one is not a role a
    42	     * permission can name (clerk or steward). */
    43	    public static Set<Role> parse(String roles) {
    44	        Set<Role> parsed = EnumSet.noneOf(Role.class);
    45	        for (String label : roles.split(",", -1)) {
    46	            Role role = Role.of(label);
    47	            if (role == null || role == Role.VIEWER) {
    48	                return null;
    49	            }
    50	            parsed.add(role);
    51	        }
    52	        return parsed;
    53	    }
    54	
    55	    /** The roles as shown: their labels, comma separated, in the order typed without repeats. */
    56	    public static String label(String roles) {
    57	        return Arrays.stream(roles.split(",", -1)).map(Role::of).map(Role::label).distinct()
    58	                .collect(Collectors.joining(","));
    59	    }
    60	
    61	    /** Whether the role may take the action. */
    62	    public boolean allows(String action, Role role) {
    63	        String roles = set.get(action);
    64	        return (roles == null ? standing(action) : parse(roles)).contains(role);
    65	    }
    66	
    67	    /** Each action's entry as shown, by action ("": blank, the standing rule). */
    68	    public Map<String, String> entries() {
    69	        Map<String, String> entries = new LinkedHashMap<>();
    70	        ACTIONS.forEach((a) -> entries.put(a, set.getOrDefault(a, "")));
    71	        return entries;
    72	    }
    73	}
