     7	import type { Claim } from './claims';
     8	import { useSelectedClaims } from './selection';
     9	import { useOneAtATime } from '../../query/useOneAtATime';
    10	
    11	// Settles every ticked claim, one after another in list order (people in their order, each one's
    12	// claims newest first), as the signed-in user — all or nothing: the server first checks every one, and
    13	// if any would be refused none is settled and every one counts as refused. Each goes through the claim's
    14	// own settle action, so a clerk's settle above the clerk limit makes it PENDING and still counts as
    15	// settled; afterwards the bulk settle's BATCH_SETTLED line is written. Every settle carries one token for the whole bulk settle, so the
    16	// claims it settles share one batch number (the sheet's next, taken by the first); beside the button is the sheet's last.
    17	export function BulkSettle() {
    18	  const [user] = useCurrentUser();
    19	  const [sheet] = useCurrentSheet();
    20	  const people = usePeople().data ?? [];
    21	  const claims = useClaims().data ?? [];
    22	  const [selected, , clear] = useSelectedClaims();
    23	  const [result, setResult] = useState<{ settled: number; refused: number } | undefined>(undefined);
    24	  const [busy, setBusy] = useState(false);
    25	  const queryClient = useQueryClient();
    26	  const once = useOneAtATime();
    27	  const lastBatch = useLastBatch().data?.last ?? null;
    28	
    29	  if (!user || !sheet) return null;
    30	
    31	  const run = async () => {
    32	    setResult(undefined);
    33	    setBusy(true);
    34	    const ordered = people.flatMap((p) => claims.filter((c) => c.personId === p.id && selected.has(c.id)));
    35	    let settled = 0;
    36	    let refused = 0;
    37	    const batch = `${Date.now().toString(36)}-${Math.random().toString(36).slice(2)}`;
    38	    const base = `/api/sheets/${encodeURIComponent(sheet)}`;
    39	    const asUser = `?user=${encodeURIComponent(user)}`;
    40	    try {
    41	      // All or nothing: a ticked claim no longer listed (gone from the sheet), or one the server would refuse to
    42	      // settle, refuses every one and nothing is settled.
    43	      let allowed = ordered.length === selected.size;
    44	      if (allowed && ordered.length > 0) {
    45	        try {
    46	          await postJson(`${base}/settle-batches/check${asUser}`, { claimIds: ordered.map((c) => c.id), batch });
    47	        } catch {
    48	          allowed = false;
    49	        }
    50	      }
    51	      if (!allowed) {
    52	        refused = selected.size;
    53	      } else {
    54	        for (const c of ordered) {
    55	          try {
    56	            await postJson<Claim>(`${base}/claims/${c.id}/settle${asUser}`, { batch });
    57	            settled++;
    58	          } catch {
    59	            refused++;
    60	          }
    61	        }
    62	        if (settled > 0) await postJson(`${base}/settle-batches/done${asUser}`, { batch });
    63	      }
    64	      clear();
    65	      await Promise.all([
    66	        queryClient.invalidateQueries({ queryKey: claimsKey(sheet) }),
    67	        queryClient.invalidateQueries({ queryKey: settleBatchesKey(sheet) }),
    68	      ]);
    69	    } finally {
    70	      setBusy(false);
    71	      setResult({ settled, refused });
    72	    }
    73	  };
    74	
    75	  return (
    76	    <p>
    77	      <button type="button" data-testid="bulk-settle" disabled={busy} onClick={() => once(run)}>
    78	        Settle selected claims
    79	      </button>{' '}
    80	      <span data-testid="bulk-settle-batch">{lastBatch ?? ''}</span>
    81	      {result && (
    82	        <>
    83	          {' '}
    84	          Settled <span data-testid="bulk-settled">{result.settled}</span>, refused{' '}
    85	          <span data-testid="bulk-settle-refused">{result.refused}</span>
    86	        </>
    87	      )}
    88	    </p>
    89	  );
    90	}
