    53	    /** The {@code days}-th business day after the date, skipping every Saturday, Sunday and one of the holidays. */
    54	    public static LocalDate businessDaysAfter(Set<LocalDate> holidays, LocalDate date, int days) {
    55	        LocalDate day = date;
    56	        int left = days;
    57	        while (left > 0) {
    58	            day = day.plusDays(1);
    59	            if (isBusinessDay(holidays, day)) {
    60	                left--;
    61	            }
    62	        }
    63	        return day;
    64	    }
