    66	    /** How many business days there are after {@code from} up to and including {@code to}: the terms that fix
    67	     * {@code to} as the due-by of a claim dated {@code from} (0 when {@code to} is not after {@code from}). */
    68	    public static int businessDaysBetween(Set<LocalDate> holidays, LocalDate from, LocalDate to) {
    69	        int days = 0;
    70	        for (LocalDate day = from.plusDays(1); !day.isAfter(to); day = day.plusDays(1)) {
    71	            if (isBusinessDay(holidays, day)) {
    72	                days++;
    73	            }
    74	        }
    75	        return days;
    76	    }
    77	
    78	    private static boolean isBusinessDay(Set<LocalDate> holidays, LocalDate day) {
    79	        DayOfWeek dow = day.getDayOfWeek();
    80	        return dow != DayOfWeek.SATURDAY && dow != DayOfWeek.SUNDAY && !holidays.contains(day);
    81	    }
    82	}
