    44	            if (NameTree.clashing(treeTaken, name, List.of())) {
    45	                throw new InvalidPersonException("A sheet related to the other sheet already has " + name + ".");
    46	            }
    47	            Person found = people.findByName(to, name);
    48	            if (found != null) {
    49	                if (into != null && !into.id().equals(found.id())) {
    50	                    throw new InvalidPersonException("More than one person on the other sheet has their names.");
    51	                }
