     1	package net.officefloor.hq.app.statement;
    24	/**
    25	 * Takes the person's statement: records their due-total now, binds each of their claims that counts to its
    26	 * due as shown now (the greater of the floor in force on its date and its figure plus any late charge on it; a due already
    27	 * bound stays as it is), and unbinds (live again) each that does not. While bound, a claim shows and totals that due: its
    28	 * late charge no longer follows the sheet's today. The due-total is their counting claims' dues added up, at most the cap
    29	 * in force on the sheet's today; n/a when their grade on the sheet's today has no rate there and no counting claim has a figure (kept, or at the
    30	 * rate for the grade in force on its date).
    31	 * <p>
    32	 * Taken as of a date (on or before the sheet's today), it works on the sheet as it stood at the end of that date — every
    33	 * change made while the sheet's today was on or before it, none made later — with that date standing in for the
    34	 * sheet's today: it binds the person's claims that counted then to their figures then, unbinds every other claim of
    35	 * theirs, and records that day's due-total and that date. Refused (400) for a date after the sheet's today, or one
    36	 * when the person was not yet on the sheet.
    37	 */
    38	public class TakeStatement {
    39	    public void take(@Val Person person, @Val StatementAsOf asOf, ClaimRepository claims, PersonRepository people,
    40	            RateRepository rates, SheetRepository sheets, SettingRepository settings, SheetDayRepository days,
    41	            Out<Statement> statement, Out<Person> updated) throws InvalidStatementException {
    42	        LocalDate today = sheets.today(person.sheetId());
    43	        LocalDate on = asOf.date() == null ? today : asOf.date();
    44	        if (on.isAfter(today)) {
    45	            throw new InvalidStatementException("A statement cannot be taken as of a date after the sheet's today.");
    46	        }
    47	        List<Claim> personClaims = claims.findForPerson(person.sheetId(), person.id());
    48	        SheetState then = asOf.date() == null ? null : days.asOf(person.sheetId(), on);
    49	        Person thenPerson = person;
    50	        List<Claim> thenClaims = personClaims;
    51	        List<Rate> sheetRates;
    52	        DatedSettings dated;
    53	        LocalDate policyDate;
    54	        if (then == null) {
    55	            sheetRates = rates.findAll(person.sheetId());
    56	            dated = settings.dated(person.sheetId());
    57	            policyDate = settings.policyDate(person.sheetId());
    58	        } else {
    59	            thenPerson = then.person(person.id());
    60	            if (thenPerson == null) {
    61	                throw new InvalidStatementException(person.name() + " was not on the sheet on " + on + ".");
    62	            }
    63	            thenClaims = then.claimsOf(person.id());
    64	            sheetRates = then.rates();
    65	            dated = then.dated();
    66	            policyDate = then.policyDate();
    67	        }
    68	        Rounding rounding = Rounding.of(policyDate == null ? on : policyDate, dated::roundingModeOn, thenClaims);
    69	        BigDecimal total = BigDecimal.ZERO.setScale(2);
    70	        boolean kept = false;
    71	        int counted = 0;
    72	        Map<Long, BigDecimal> figures = new HashMap<>();
    73	        for (Claim claim : thenClaims) {
    74	            if (!thenPerson.counts(claim, on)) {
    75	                continue;
    76	            }
    77	            boolean fixed = claim.keepsFigure();
    78	            BigDecimal rate = Rate.inForce(sheetRates, thenPerson.gradeOn(claim.date()), claim);
    79	            BigDecimal figure = claim.figure(rate, rounding);
    80	            BigDecimal due = figure == null ? null
    81	                    : claim.due(rate, dated.floorOn(claim.date()), dated.lateCharge(on, thenPerson), rounding);
    82	            figures.put(claim.id(), due);
    83	            counted++;
    84	            kept |= fixed || figure != null;
    85	            if (due != null) {
    86	                total = total.add(due);
    87	            }
    88	        }
    89	        for (Claim claim : personClaims) {
    90	            boolean stated = figures.containsKey(claim.id());
    91	            claims.bindStatement(claim, stated, stated ? figures.get(claim.id()) : null);
    92	        }
    93	        String dueTotal = Rate.inForce(sheetRates, thenPerson.gradeOn(on), on) == null && !kept ? "n/a"
    94	                : Cap.apply(dated.capOn(on), total).setScale(2).toPlainString();
    95	        statement.set(new Statement(person.name(), dueTotal, counted, asOf.date()));
    96	        updated.set(people.recordStatement(person, dueTotal, on));
    97	    }
    98	}
