     1	package net.officefloor.hq.app.asof;
     2	
     3	import java.sql.Connection;
     4	import java.sql.SQLException;
     5	import java.sql.Statement;
     6	import javax.sql.DataSource;
     7	import org.springframework.beans.factory.config.BeanPostProcessor;
     8	import org.springframework.jdbc.datasource.DelegatingDataSource;
     9	import org.springframework.stereotype.Component;
    10	
    11	/**
    12	 * Every connection is handed out reading the store as it stands now, or, for a request reading the sheet as of a date
    13	 * ({@link AsOfView}), reading that date's schema with the date as the sheet's today. Set on every hand-out, so a
    14	 * pooled connection never passes one request's view on to the next.
    15	 */
    16	@Component
    17	public class AsOfConnections implements BeanPostProcessor {
    18	
    19	    @Override
    20	    public Object postProcessAfterInitialization(Object bean, String beanName) {
    21	        if (bean instanceof DataSource dataSource && !(bean instanceof DelegatingDataSource)) {
    22	            return new DelegatingDataSource(dataSource) {
    23	                @Override
    24	                public Connection getConnection() throws SQLException {
    25	                    return viewed(super.getConnection());
    26	                }
    27	
    28	                @Override
    29	                public Connection getConnection(String username, String password) throws SQLException {
    30	                    return viewed(super.getConnection(username, password));
    31	                }
    32	            };
    33	        }
    34	        return bean;
    35	    }
    36	
    37	    private static Connection viewed(Connection connection) throws SQLException {
    38	        AsOfView view = AsOfView.current();
    39	        try (Statement s = connection.createStatement()) {
    40	            if (view == null) {
    41	                s.execute("SET SCHEMA PUBLIC");
    42	                s.execute("SET @asof = NULL");
    43	            } else {
    44	                s.execute("SET SCHEMA " + view.schema());
    45	                s.execute("SET @asof = DATE '" + view.date() + "'");
    46	            }
    47	        }
    48	        return connection;
    49	    }
    50	}
