     2	
     3	import jakarta.servlet.FilterChain;
     4	import jakarta.servlet.ServletException;
     5	import jakarta.servlet.http.HttpServletRequest;
     6	import jakarta.servlet.http.HttpServletResponse;
     7	import java.io.IOException;
     8	import java.net.URLDecoder;
     9	import java.nio.charset.StandardCharsets;
    10	import java.time.LocalDate;
    11	import java.time.format.DateTimeParseException;
    12	import java.util.regex.Matcher;
    13	import java.util.regex.Pattern;
    14	import org.springframework.core.Ordered;
    15	import org.springframework.core.annotation.Order;
    16	import org.springframework.http.HttpStatus;
    17	import org.springframework.stereotype.Component;
    18	import org.springframework.web.filter.OncePerRequestFilter;
    19	
    20	/**
    21	 * A read of a sheet ({@code GET /api/sheets/<id>...}) with {@code ?asOf=<yyyy-MM-dd>} reads the whole sheet as it
    22	 * stood at the end of the last day on or before that date ({@link SheetDayRepository#schemaAsOf}), with the date
    23	 * standing in for the sheet's today: every endpoint reads it unchanged, as every connection the request takes is
    24	 * pointed at that sheet. Only reads are viewed so; a change is never made as of a date.
    25	 */
    26	@Component
    27	@Order(Ordered.HIGHEST_PRECEDENCE)
    28	public class AsOfFilter extends OncePerRequestFilter {
    29	
    30	    private static final Pattern SHEET_READ = Pattern.compile("^/api/sheets/([^/]+)(/.*)?$");
    31	
    32	    private final SheetDayRepository days;
    33	
    34	    public AsOfFilter(SheetDayRepository days) {
    35	        this.days = days;
    36	    }
    37	
    38	    @Override
    39	    protected void doFilterInternal(HttpServletRequest request, HttpServletResponse response, FilterChain chain)
    40	            throws ServletException, IOException {
    41	        String asOf = request.getParameter("asOf");
    42	        Matcher read = SHEET_READ.matcher(request.getRequestURI());
    43	        if (!"GET".equals(request.getMethod()) || asOf == null || asOf.isBlank() || !read.matches()) {
    44	            AsOfView.set(null);
    45	            chain.doFilter(request, response);
    46	            return;
    47	        }
    48	        LocalDate date;
    49	        try {
    50	            date = LocalDate.parse(asOf.trim());
    51	        } catch (DateTimeParseException e) {
    52	            response.sendError(HttpStatus.BAD_REQUEST.value(), "Not a date: " + asOf);
    53	            return;
    54	        }
    55	        String sheetId = URLDecoder.decode(read.group(1), StandardCharsets.UTF_8);
    56	        AsOfView.set(null);
    57	        String schema = days.schemaAsOf(sheetId, date);
    58	        AsOfView.set(new AsOfView(schema, date));
    59	        try {
    60	            chain.doFilter(request, response);
    61	        } finally {
    62	            AsOfView.set(null);
    63	        }
    64	    }
