   124	                + " WHERE t.TABLE_SCHEMA = 'PUBLIC' AND t.TABLE_TYPE = 'BASE TABLE' AND EXISTS (SELECT 1 FROM"
   125	                + " INFORMATION_SCHEMA.COLUMNS c WHERE c.TABLE_SCHEMA = 'PUBLIC' AND c.TABLE_NAME = t.TABLE_NAME"
