   140	        try (PreparedStatement p = c.prepareStatement("SELECT t.TABLE_NAME FROM INFORMATION_SCHEMA.TABLES t"
   141	                + " WHERE t.TABLE_SCHEMA = 'PUBLIC' AND t.TABLE_TYPE = 'BASE TABLE' AND EXISTS (SELECT 1 FROM"
   142	                + " INFORMATION_SCHEMA.COLUMNS c WHERE c.TABLE_SCHEMA = 'PUBLIC' AND c.TABLE_NAME = t.TABLE_NAME"
   143	                + " AND c.COLUMN_NAME = 'POOL_ID') AND NOT EXISTS (SELECT 1 FROM INFORMATION_SCHEMA.COLUMNS c"
   144	                + " WHERE c.TABLE_SCHEMA = 'PUBLIC' AND c.TABLE_NAME = t.TABLE_NAME AND c.COLUMN_NAME = 'SHEET_ID')"
   145	                + " ORDER BY t.TABLE_NAME"); ResultSet rs = p.executeQuery()) {
   146	            while (rs.next()) {
