   157	    private static String sheetColumns(Connection c, boolean defaults) throws SQLException {
   158	        List<String> columns = new ArrayList<>();
   159	        try (PreparedStatement p = c.prepareStatement("SELECT COLUMN_NAME, COLUMN_DEFAULT, DATA_TYPE,"
   160	                + " NUMERIC_PRECISION, NUMERIC_SCALE, CHARACTER_MAXIMUM_LENGTH FROM INFORMATION_SCHEMA.COLUMNS"
   161	                + " WHERE TABLE_SCHEMA = 'PUBLIC' AND TABLE_NAME = 'SHEET' ORDER BY ORDINAL_POSITION");
