 60	 * that boundary date (the due-by plus the grace plus 30, 60, 90 ... days) of its figure plus the charges of the
 61	 * boundaries before it (compounding), rounded like the claim's due, the charges added up; a boundary whose percent is 0.00 adds nothing. It follows the
 62	 * sheet's today until the claim is settled, or while a statement binds the claim's due (charge included). A correction, a deferred claim and a claim whose
 63	 * charge was waived is never charged.
 64	 */
 65	public record LateCharge(Function<LocalDate, BigDecimal> pctOn, Function<Claim, Integer> graceOf, LocalDate today) {
 66	
 67	    /** A charge with no grace days for any claim. */
 68	    public LateCharge(Function<LocalDate, BigDecimal> pctOn, LocalDate today) {
 69	        this(pctOn, (claim) -> 0, today);
 70	    }
 71	
 72	    /** The days in each period an overdue claim is charged for. */
 73	    public static final int PERIOD_DAYS = 30;
 74	
 75	    /** The charge on the claim's figure (null: n/a, charged nothing); zero unless the claim is overdue. */
 76	    public BigDecimal on(Claim claim, BigDecimal figure, RoundingMode mode) {
 77	        BigDecimal charge = BigDecimal.ZERO.setScale(2);
 78	        if (figure == null || !claim.status().open() || claim.deferred(today) || claim.correction() || claim.waived()) {
 79	            return charge;
 80	        }
 81	        LocalDate lateFrom = claim.dueBy().plusDays(graceOf.apply(claim));
 82	        long late = ChronoUnit.DAYS.between(lateFrom, today);
 83	        long periods = late > 0 ? late / PERIOD_DAYS : 0;
 84	        for (long period = 1; period <= periods; period++) {
 85	            BigDecimal pct = pctOn.apply(lateFrom.plusDays(period * PERIOD_DAYS));
 86	            if (pct.signum() != 0) {
 87	                charge = charge.add(Claim.due(figure.add(charge), pct, mode));
 88	            }
 89	        }
 90	        return charge;
 91	    }
 92	}
