105	/**
106	 * A rate a sheet has for a grade: a percent with two decimals, in force from {@code from} (null: from
107	 * the beginning of time) until the grade's next rate takes over, or through {@code to} (null: no end), whichever
108	 * comes first. A rate is kept as versions, one per time it was set for its grade and from-date: this is the newest
109	 * (the one in force), {@code version} its number (from 1), so how many versions it has. A rate saved with a from-date
110	 * on or after the sheet's today is {@code forward}-only: it applies only to claims added after it was saved ({@code saved},
111	 * on the sequence a claim's {@link Claim#added} is on); a claim added before keeps the {@code earlier} version that applied
112	 * to it (null: none, so the grade has no rate for that from-date for it).
113	 */
114	public record Rate(String sheetId, String grade, BigDecimal rate, LocalDate from, LocalDate to, int version,
115	        boolean forward, long saved, Rate earlier) {
116	
117	    /** The same version with the one before it. */
118	    public Rate withEarlier(Rate before) {
119	        return new Rate(sheetId, grade, rate, from, to, version, forward, saved, before);
120	    }
121	
122	    /** Whether this version applies to a claim added at {@code added}. */
123	    public boolean appliesTo(long added) {
124	        return !forward || added > saved;
125	    }
126	
127	    /** The newest version of this rate that applies to a claim added at {@code added}; null with none. */
128	    public Rate forClaim(long added) {
129	        Rate version = this;
130	        while (version != null && !version.appliesTo(added)) {
131	            version = version.earlier();
132	        }
133	        return version;
134	    }
135	
136	    /**
137	     * The rate for the claim's person's grade on the claim's date, as {@link #inForce(List, String, LocalDate)}, from the
138	     * versions of the rates that apply to the claim.
139	     */
140	    public static BigDecimal inForce(List<Rate> rates, String grade, Claim claim) {
141	        return inForce(rates.stream().map((r) -> r.forClaim(claim.added())).filter(Objects::nonNull).toList(), grade,
142	                claim.date());
143	    }
144	
145	    /**
146	     * The grade's rate in force on the date: the one with the latest from-date on or before it, unless its to-date
147	     * is before the date. The rates may be those of a sheet followed by its parent's (and so on up): the first sheet,
148	     * in that order, with a rate in force gives it; null with none.
149	     */
150	    public static BigDecimal inForce(List<Rate> rates, String grade, LocalDate date) {
151	        Map<String, List<Rate>> bySheet = new LinkedHashMap<>();
152	        rates.forEach((r) -> bySheet.computeIfAbsent(r.sheetId(), (k) -> new ArrayList<>()).add(r));
153	        for (List<Rate> sheetRates : bySheet.values()) {
154	            BigDecimal rate = ownInForce(sheetRates, grade, date);
155	            if (rate != null) {
156	                return rate;
157	            }
158	        }
159	        return null;
160	    }
161	
162	    private static BigDecimal ownInForce(List<Rate> rates, String grade, LocalDate date) {
163	        return rates.stream()
164	                .filter((r) -> r.grade().equals(grade) && (r.from() == null || !r.from().isAfter(date)))
165	                .max(Comparator.comparing(Rate::from, Comparator.nullsFirst(Comparator.naturalOrder())))
166	                .filter((r) -> r.to() == null || !r.to().isBefore(date))
167	                .map(Rate::rate).orElse(null);
168	    }
169	}
