 10	public record Pools(List<Pool> list, BigDecimal pot) {
 11	
 12	    /** The pool this one is a member of, or null. */
 13	    public Pool parentOf(long poolId) {
 14	        return list.stream().filter(p -> p.members().stream().anyMatch(m -> m.poolId() != null && m.poolId() == poolId))
 15	                .findFirst().orElse(null);
 16	    }
 17	
 18	    /** The pool's pot: the sheet's when it is a member of no pool, else its cut in the pool above (null: none). */
 19	    public BigDecimal potOf(Pool pool) {
 20	        return potOf(pool, 0);
 21	    }
 22	
 23	    private BigDecimal potOf(Pool pool, int depth) {
 24	        Pool parent = parentOf(pool.id());
 25	        if (parent == null) {
 26	            return pot;
 27	        }
 28	        if (depth > list.size()) {
 29	            return null; // a cycle, which validation never lets in
 30	        }
 31	        List<BigDecimal> cuts = PoolResponse.cuts(parent, potOf(parent, depth + 1));
 32	        if (cuts == null) {
 33	            return null;
 34	        }
 35	        for (int i = 0; i < parent.members().size(); i++) {
 36	            Long id = parent.members().get(i).poolId();
 37	            if (pool.id().equals(id)) {
 38	                return cuts.get(i);
 39	            }
 40	        }
 41	        return null;
 42	    }
 43	
 44	    /** The number of levels of pools from this one down (1: no pool members). */
 45	    public int height(long poolId) {
 46	        return height(poolId, 0);
 47	    }
 48	
 49	    private int height(long poolId, int guard) {
 50	        Pool pool = find(poolId);
 51	        if (pool == null || guard > list.size()) {
 52	            return 1;
 53	        }
 54	        int below = 0;
 55	        for (PoolMember m : pool.members()) {
 56	            if (m.poolId() != null) {
 57	                below = Math.max(below, height(m.poolId(), guard + 1));
 58	            }
 59	        }
 60	        return 1 + below;
 61	    }
 62	
 63	    /** The number of pools from this one up to the one that is a member of none (1: a member of none). */
 64	    public int level(long poolId) {
 65	        int level = 1;
 66	        Pool parent = parentOf(poolId);
 67	        while (parent != null && level <= list.size()) {
 68	            level++;
 69	            parent = parentOf(parent.id());
 70	        }
 71	        return level;
 72	    }
 73	
 74	    /** Whether {@code poolId} is {@code ancestor} or lies under it through any chain of pool members. */
 75	    public boolean within(long poolId, long ancestor) {
 76	        Long at = poolId;
 77	        for (int i = 0; at != null && i <= list.size(); i++) {
 78	            if (at == ancestor) {
 79	                return true;
 80	            }
 81	            Pool parent = parentOf(at);
 82	            at = parent == null ? null : parent.id();
 83	        }
 84	        return false;
 85	    }
 86	
 87	    /** The pool with this id, or null. */
 88	    public Pool find(long poolId) {
 89	        return list.stream().filter(p -> p.id() == poolId).findFirst().orElse(null);
 90	    }
 91	}
