100	/**
101	 * A pool as the screen reads it: its members' shares with two decimals and their membership dates (null: no start /
102	 * no end), the total share (a retired member's share, whatever their retirement date, counts as given; a member whose
103	 * dates do not include the sheet's today is left out entirely: not in the total, no cut, "" for its cut) and whether that total is exactly 100.00. In a balanced pool, with a
104	 * pot, each member with a cut (neither retired nor held on the sheet's today) gets the pot times their share divided by
105	 * the shares of the members with a cut added up, rounded half to even to two decimals (a retired or held member's is
106	 * 0.00, so a hold spreads its share over the others); the remainder (the pot less the cuts added up) goes to the member
107	 * with the smallest non-zero cut, the latest added on a tie (a member with no cut gets none; when no cut is non-zero, it
108	 * goes to the last member with a cut and a share), so the cuts total exactly the pot (when no member has
109	 * a cut, each is 0.00; when every member in the pool is retired, there are no cuts). Otherwise a member's cut is "" (none). A member is a
110	 * person ({@code personId}) or another pool ({@code poolId}); the pool's pot is the sheet's when it is a member of no
111	 * pool, else its cut in the pool above (null: none). A crew's pool ({@code crew}) has the crew's id negated as its id.
112	 * Each member also has its cut at the end of each period whose to-date is on or before the sheet's today
113	 * ({@code periodCuts}, earliest first), worked out the same way from the pool, its members, the pot and the holds as
114	 * they were then with that day as the sheet's today ("" when there was none).
115	 */
116	public record PoolResponse(long id, String name, List<Member> members, String totalShare, boolean balanced,
117	        boolean crew) {
118	
119	    public record Member(Long personId, Long poolId, String name, String share, boolean retired, String cut,
120	            String from, String to, List<PeriodCut> periodCuts) {
121	    }
122	
123	    /** A member's cut at the end of the named period ("": none). */
124	    public record PeriodCut(String period, String cut) {
125	    }
126	
127	    private static final BigDecimal HUNDRED = new BigDecimal("100.00");
128	
129	    public static PoolResponse from(Pool pool, BigDecimal pot, PoolHistory history) {
130	        BigDecimal total = total(pool);
131	        boolean balanced = total.compareTo(HUNDRED) == 0;
132	        List<BigDecimal> cuts = cuts(pool, pot);
133	        List<Member> members = new ArrayList<>();
134	        for (int i = 0; i < pool.members().size(); i++) {
135	            PoolMember m = pool.members().get(i);
136	            members.add(new Member(m.personId(), m.poolId(), m.name(), m.share().setScale(2).toPlainString(),
137	                    m.retired(), cuts == null || cuts.get(i) == null ? "" : cuts.get(i).toPlainString(),
138	                    m.from() == null ? null : m.from().toString(), m.to() == null ? null : m.to().toString(),
139	                    periodCuts(pool, m, history)));
140	        }
141	        return new PoolResponse(pool.id(), pool.name(), members, total.toPlainString(), balanced, pool.id() < 0);
142	    }
143	
144	    /** The member's cut at the end of each period of the history: "" when the pool or the member was not there then. */
145	    private static List<PeriodCut> periodCuts(Pool pool, PoolMember member, PoolHistory history) {
146	        List<PeriodCut> cuts = new ArrayList<>();
147	        for (PoolHistory.Ended ended : history.periods()) {
148	            cuts.add(new PeriodCut(ended.period(), cutThen(pool, member, ended.pools())));
149	        }
150	        return cuts;
151	    }
152	
153	    private static String cutThen(Pool pool, PoolMember member, Pools then) {
154	        Pool was = then.find(pool.id());
155	        if (was == null) {
156	            return "";
157	        }
158	        List<BigDecimal> cuts = cuts(was, then.potOf(was));
159	        if (cuts == null) {
160	            return "";
161	        }
162	        for (int i = 0; i < was.members().size(); i++) {
163	            PoolMember m = was.members().get(i);
164	            if (Objects.equals(m.personId(), member.personId())
165	                    && Objects.equals(m.poolId(), member.poolId())) {
166	                return cuts.get(i) == null ? "" : cuts.get(i).toPlainString();
167	            }
168	        }
169	        return "";
170	    }
171	
172	    /** The pool's total share: its members' shares added up, a retired member's counting as given, an out one's not. */
173	    static BigDecimal total(Pool pool) {
174	        return pool.members().stream().filter(m -> !m.out()).map(PoolMember::share)
175	                .reduce(BigDecimal.ZERO, BigDecimal::add).setScale(2);
176	    }
177	
178	    /**
179	     * Each member's cut of the pot, in the members' order; the remainder goes to the smallest non-zero cut,
180	     * latest on a tie (none non-zero: the last member with a cut and a share).
181	     * An out member's (its dates leave out the sheet's today) is null: none. Null when the pool is unbalanced or there
182	     * is no pot, or when every member in the pool on the sheet's today is retired.
183	     */
184	    static List<BigDecimal> cuts(Pool pool, BigDecimal pot) {
185	        if (pot == null || total(pool).compareTo(HUNDRED) != 0) {
186	            return null;
187	        }
188	        List<PoolMember> members = pool.members();
189	        if (members.stream().filter(m -> !m.out()).allMatch(PoolMember::retired)) {
190	            return null;
191	        }
192	        BigDecimal base = members.stream().filter(PoolMember::cut).map(PoolMember::share)
193	                .reduce(BigDecimal.ZERO, BigDecimal::add);
194	        List<BigDecimal> cuts = new ArrayList<>();
195	        BigDecimal sum = BigDecimal.ZERO;
196	        int smallest = -1;
197	        int lastShared = -1;
198	        for (int i = 0; i < members.size(); i++) {
199	            PoolMember m = members.get(i);
200	            if (m.out()) {
201	                cuts.add(null);
202	                continue;
203	            }
204	            BigDecimal cut = !m.cut() ? BigDecimal.ZERO.setScale(2)
205	                    : pot.multiply(m.share()).divide(base, 2, RoundingMode.HALF_EVEN);
206	            cuts.add(cut);
207	            sum = sum.add(cut);
208	            if (m.cut() && cut.signum() != 0 && (smallest < 0 || cut.compareTo(cuts.get(smallest)) <= 0)) {
209	                smallest = i;
210	            }
211	            if (m.cut() && m.share().signum() != 0) {
212	                lastShared = i;
213	            }
214	        }
215	        int to = smallest >= 0 ? smallest : lastShared;
216	        if (to >= 0) {
217	            cuts.set(to, cuts.get(to).add(pot.subtract(sum)));
218	        }
219	        return cuts;
220	    }
221	}
