40	     */
41	    public List<Pool> findAll(String sheetId, LocalDate today, boolean then) {
42	        Date on = today == null ? null : Date.valueOf(today);
43	        Date upTo = then ? on : null;
44	        Map<Long, Pool> pools = new LinkedHashMap<>();
45	        jdbc.query("SELECT id, name FROM pool WHERE sheet_id = ?" + ADDED.formatted("") + " ORDER BY id", rs -> {
46	            long id = rs.getLong("id");
47	            pools.put(id, new Pool(id, sheetId, rs.getString("name"), new ArrayList<>()));
48	        }, sheetId, upTo, upTo);
49	        jdbc.query("SELECT m.pool_id, m.person_id, m.member_pool_id, m.share, m.from_date, m.to_date, p.name,"
50	                + " p.retired_from, q.name AS pool_name,"
51	                + " CASE WHEN EXISTS (SELECT 1 FROM person_hold h WHERE h.person_id = m.person_id AND CAST(? AS DATE) IS NOT NULL"
52	                + " AND (h.from_date IS NULL OR h.from_date <= CAST(? AS DATE))"
53	                + " AND (h.to_date IS NULL OR h.to_date >= CAST(? AS DATE))" + ADDED.formatted("h.") + ") THEN 1 ELSE 0 END AS held"
54	                + " FROM pool_member m JOIN pool o ON o.id = m.pool_id LEFT JOIN person p ON p.id = m.person_id"
55	                + " LEFT JOIN pool q ON q.id = m.member_pool_id WHERE o.sheet_id = ?" + ADDED.formatted("o.")
56	                + ADDED.formatted("m.") + " ORDER BY m.id",
57	                rs -> {
58	                    Pool pool = pools.get(rs.getLong("pool_id"));
59	                    Date fromDate = rs.getDate("from_date");
60	                    Date toDate = rs.getDate("to_date");
61	                    LocalDate from = fromDate == null ? null : fromDate.toLocalDate();
62	                    LocalDate to = toDate == null ? null : toDate.toLocalDate();
63	                    boolean out = !PoolMember.includes(from, to, today);
64	                    long personId = rs.getLong("person_id");
65	                    if (rs.wasNull()) {
66	                        pool.members().add(new PoolMember(null, rs.getLong("member_pool_id"),
67	                                rs.getString("pool_name"), rs.getBigDecimal("share"), false, false, from, to, out));
68	                    } else {
69	                        pool.members().add(new PoolMember(personId, null, rs.getString("name"),
70	                                rs.getBigDecimal("share"), rs.getDate("retired_from") != null, rs.getInt("held") == 1,
71	                                from, to, out));
72	                    }
73	                }, on, on, on, upTo, upTo, sheetId, upTo, upTo, upTo, upTo);
74	        return new ArrayList<>(pools.values());
