77	    /**
78	     * The sheet's crews as pools, in the order the crews were added: each named as its crew, with id the crew's id
79	     * negated (so it is never a stored pool's), and the lead then the members as its members at equal shares of 100.00
80	     * (each rounded half to even to two decimals, the remainder on the lead — on the first member when it has none — as patrons' shares are split); a person
81	     * member is held when a hold of theirs is in force on {@code today} (null: none is held).
82	     */
83	    public List<Pool> crewPools(String sheetId, LocalDate today) {
84	        return crewPools(sheetId, today, false);
85	    }
