87	    /**
88	     * The sheet's crews as pools as {@link #crewPools(String, LocalDate)} gives them; when {@code then}, as they stood at
89	     * the end of {@code today}: only the crews, members and holds added on or before it.
90	     */
91	    public List<Pool> crewPools(String sheetId, LocalDate today, boolean then) {
92	        Date on = today == null ? null : Date.valueOf(today);
93	        Date upTo = then ? on : null;
94	        Map<Long, Pool> pools = new LinkedHashMap<>();
95	        String held = " CASE WHEN EXISTS (SELECT 1 FROM person_hold h WHERE h.person_id = p.id AND CAST(? AS DATE) IS NOT NULL"
96	                + " AND (h.from_date IS NULL OR h.from_date <= CAST(? AS DATE))"
97	                + " AND (h.to_date IS NULL OR h.to_date >= CAST(? AS DATE))" + ADDED.formatted("h.") + ") THEN 1 ELSE 0 END AS held";
98	        jdbc.query("SELECT c.id, c.name, p.id AS person_id, p.name AS person_name, p.retired_from," + held
99	                + " FROM crew c LEFT JOIN person p ON p.id = c.lead_id WHERE c.sheet_id = ?" + ADDED.formatted("c.")
100	                + " ORDER BY c.id", rs -> {
101	                    long id = rs.getLong("id");
102	                    Pool pool = new Pool(-id, sheetId, rs.getString("name"), new ArrayList<>());
103	                    rs.getLong("person_id");
104	                    if (!rs.wasNull()) {
105	                        pool.members().add(crewMember(rs));
106	                    }
107	                    pools.put(id, pool);
108	                }, on, on, on, upTo, upTo, sheetId, upTo, upTo);
109	        jdbc.query("SELECT m.crew_id, p.id AS person_id, p.name AS person_name, p.retired_from," + held
110	                + " FROM crew_member m JOIN person p ON p.id = m.person_id WHERE m.sheet_id = ?" + ADDED.formatted("m.")
111	                + " ORDER BY m.id",
112	                rs -> {
113	                    Pool crew = pools.get(rs.getLong("crew_id"));
114	                    if (crew != null) {
115	                        crew.members().add(crewMember(rs));
116	                    }
117	                }, on, on, on, upTo, upTo, sheetId, upTo, upTo);
118	        List<Pool> list = new ArrayList<>();
119	        for (Pool pool : pools.values()) {
120	            int n = pool.members().size();
121	            if (n == 0) {
122	                list.add(pool);
123	                continue;
124	            }
125	            BigDecimal share = HUNDRED.divide(BigDecimal.valueOf(n), 2, RoundingMode.HALF_EVEN);
126	            BigDecimal lead = HUNDRED.subtract(share.multiply(BigDecimal.valueOf(n))).add(share);
127	            List<PoolMember> members = new ArrayList<>();
128	            for (int i = 0; i < n; i++) {
129	                PoolMember m = pool.members().get(i);
130	                members.add(new PoolMember(m.personId(), null, m.name(), i == 0 ? lead : share, m.retired(), m.held(),
131	                        null, null, false));
132	            }
133	            list.add(new Pool(pool.id(), sheetId, pool.name(), members));
134	        }
135	        return list;
136	    }
