139	     * A condition that the row (its columns under the prefix given) was added on or before a date: its two parameters
140	     * are the date (null: any row).
141	     */
142	    private static final String ADDED = " AND (CAST(? AS DATE) IS NULL OR %1$sadded_on IS NULL OR %1$sadded_on <= CAST(? AS DATE))";
143	
144	    private static final BigDecimal HUNDRED = new BigDecimal("100.00");
145	
146	    /** A crew's lead or member as a pool member, its share unset. */
147	    private static PoolMember crewMember(java.sql.ResultSet rs) throws java.sql.SQLException {
148	        return new PoolMember(rs.getLong("person_id"), null, rs.getString("person_name"), null,
149	                rs.getDate("retired_from") != null, rs.getInt("held") == 1, null, null, false);
150	    }
