 15	@Repository
 16	public class SheetRepository {
 17	
 18	    private final JdbcTemplate jdbc;
 19	
 20	    public SheetRepository(JdbcTemplate jdbc) {
 21	        this.jdbc = jdbc;
 22	    }
 23	
 24	    /** The sheet with this id, created empty (today = the real date) when it was never loaded before. */
 25	    public Sheet ensure(String id) {
 26	        jdbc.update("INSERT INTO sheet (id, today, started) SELECT ?, ?, ? WHERE NOT EXISTS (SELECT 1 FROM sheet WHERE id = ?)",
 27	                id, Date.valueOf(LocalDate.now()), Date.valueOf(LocalDate.now()), id);
 28	        return find(id);
 29	    }
 30	
 31	    /** The sheet with this id, or null when it was never loaded. */
 32	    public Sheet find(String id) {
 33	        List<Sheet> found = jdbc.query("SELECT id, today, archived FROM sheet WHERE id = ?",
 34	                (rs, n) -> new Sheet(rs.getString("id"), rs.getDate("today").toLocalDate(), rs.getBoolean("archived")),
 35	                id);
 36	        return found.isEmpty() ? null : found.get(0);
 37	    }
 38	
 39	    /**
 40	     * The sheet's today. Use this — never {@code LocalDate.now()} — for any date-dependent decision
 41	     * or default date in the sheet.
 42	     */
 43	    public LocalDate today(String id) {
 44	        Sheet sheet = find(id);
 45	        return sheet == null ? LocalDate.now() : sheet.today();
 46	    }
 47	
 48	    /**
 49	     * The date a new claim left without one takes: the sheet's entry date while it is set, else its today.
 50	     */
 51	    public LocalDate entryDate(String id) {
 52	        List<Date> found = jdbc.query("SELECT entry_date FROM sheet WHERE id = ?", (rs, n) -> rs.getDate("entry_date"), id);
 53	        return found.isEmpty() || found.get(0) == null ? today(id) : found.get(0).toLocalDate();
 54	    }
 55	
 56	    /**
 57	     * Takes the next claim number of the sheet's tree (1 for its first): one after the last number given on any sheet
 58	     * of the tree, in one atomic statement that moves every sheet of the tree on to it, so two claims opened at the
 59	     * same moment never get the same number; a number taken is never given out again.
 60	     */
 61	    public int nextClaimNumber(String id) {
 62	        List<String> tree = tree(id);
 63	        String in = String.join(", ", Collections.nCopies(tree.size(), "?"));
 64	        Object[] args = new Object[tree.size() * 2];
 65	        for (int i = 0; i < tree.size(); i++) {
 66	            args[i] = tree.get(i);
 67	            args[tree.size() + i] = tree.get(i);
 68	        }
 69	        List<Integer> taken = jdbc.queryForList("SELECT last_claim_number FROM FINAL TABLE (UPDATE sheet SET"
 70	                + " last_claim_number = (SELECT MAX(t.last_claim_number) FROM sheet t WHERE t.id IN (" + in + ")) + 1"
 71	                + " WHERE id IN (" + in + "))", Integer.class, args);
 72	        return taken.get(0);
 73	    }
 74	
 75	    /**
 76	     * Takes the next claim number of the sheet's tree within a fiscal year (1 for its first in that year), as
 77	     * {@link #nextClaimNumber} does: one after the last number of that year given on any sheet of the tree, moving
 78	     * every sheet of the tree on to it in one atomic statement; a number taken is never given out again.
 79	     */
 80	    public int nextFiscalClaimNumber(String id, int fiscalYear) {
 81	        List<String> tree = tree(id);
 82	        for (String sheetId : tree) {
 83	            jdbc.update("MERGE INTO fiscal_claim_number f USING (VALUES (CAST(? AS VARCHAR(100)), CAST(? AS INT)))"
 84	                    + " AS v (sheet_id, fiscal_year) ON f.sheet_id = v.sheet_id AND f.fiscal_year = v.fiscal_year"
 85	                    + " WHEN NOT MATCHED THEN INSERT (sheet_id, fiscal_year, last_number)"
 86	                    + " VALUES (v.sheet_id, v.fiscal_year, 0)", sheetId, fiscalYear);
 87	        }
 88	        String in = String.join(", ", Collections.nCopies(tree.size(), "?"));
 89	        List<Object> args = new ArrayList<>(tree);
 90	        args.add(fiscalYear);
 91	        args.addAll(tree);
 92	        args.add(fiscalYear);
 93	        List<Integer> taken = jdbc.queryForList("SELECT last_number FROM FINAL TABLE (UPDATE fiscal_claim_number SET"
 94	                + " last_number = (SELECT MAX(t.last_number) FROM fiscal_claim_number t WHERE t.sheet_id IN (" + in
 95	                + ") AND t.fiscal_year = ?) + 1 WHERE sheet_id IN (" + in + ") AND fiscal_year = ?)", Integer.class,
 96	                args.toArray());
 97	        return taken.get(0);
 98	    }
 99	
100	    /**
101	     * The ids of the sheets of the sheet's tree, the sheet among them: its topmost existing ancestor and every sheet
102	     * below that (the sheets naming it as their parent, their children and so on).
103	     */
104	    public List<String> tree(String id) {
105	        Set<String> seen = new HashSet<>(List.of(id));
106	        String root = id;
107	        for (String up = parent(id); up != null && find(up) != null && seen.add(up); up = parent(up)) {
108	            root = up;
109	        }
110	        LinkedHashSet<String> found = new LinkedHashSet<>(List.of(root, id));
111	        List<String> todo = new ArrayList<>(List.of(root));
112	        while (!todo.isEmpty()) {
113	            String at = todo.remove(0);
114	            for (String child : jdbc.queryForList("SELECT id FROM sheet WHERE parent_id = ? ORDER BY id", String.class,
115	                    at)) {
116	                if (found.add(child)) {
117	                    todo.add(child);
118	                }
119	            }
120	        }
121	        return List.copyOf(found);
122	    }
123	
124	    /**
125	     * Takes the next number (1 for its first) of one of the sheet's per-period sequences: {@code key} is the
126	     * period's name in lower case, or "" for the claims in no period. A number taken is never given out again.
127	     */
128	    public int nextPeriodClaimNumber(String id, String key) {
129	        for (int attempt = 0; ; attempt++) {
130	            List<Integer> taken = jdbc.queryForList("SELECT last_number FROM FINAL TABLE (UPDATE period_claim_number"
131	                    + " SET last_number = last_number + 1 WHERE sheet_id = ? AND seq_key = ?)", Integer.class, id, key);
132	            if (!taken.isEmpty()) {
133	                return taken.get(0);
134	            }
135	            try {
136	                jdbc.update("INSERT INTO period_claim_number (sheet_id, seq_key, last_number) VALUES (?, ?, 1)", id, key);
137	                return 1;
138	            } catch (DuplicateKeyException e) {
139	                if (attempt > 0) {
140	                    throw e;
141	                }
142	                // another request started the sequence at the same moment: take the next from it
143	            }
144	        }
145	    }
146	
147	    /** The sheet's parent sheet id as the store holds it now (null: none); it is not dated, so an as-of view shows it too. */
148	    public String parent(String id) {
149	        List<String> found = jdbc.query("SELECT parent_id FROM PUBLIC.sheet WHERE id = ?", (rs, n) -> rs.getString("parent_id"), id);
150	        return found.isEmpty() ? null : found.get(0);
151	    }
152	
153	    /**
154	     * The sheet's descendants: its children (the sheets naming it as their parent), their children and so on,
155	     * each once, nearest first; the sheet itself never, even where parents loop back to it.
156	     */
157	    public List<String> descendants(String id) {
158	        LinkedHashSet<String> found = new LinkedHashSet<>();
159	        java.util.ArrayDeque<String> todo = new java.util.ArrayDeque<>(List.of(id));
160	        while (!todo.isEmpty()) {
161	            String at = todo.poll();
162	            for (String child : jdbc.queryForList("SELECT id FROM PUBLIC.sheet WHERE parent_id = ? ORDER BY id", String.class, at)) {
163	                if (!child.equals(id) && found.add(child)) {
164	                    todo.add(child);
165	                }
166	            }
167	        }
168	        return List.copyOf(found);
169	    }
170	
171	    /** Whether the sheet is archived: every change to an archived sheet is refused. */
172	    public boolean isArchived(String id) {
173	        Sheet sheet = find(id);
174	        return sheet != null && sheet.archived();
175	    }
176	
177	    public void save(Sheet sheet) {
178	        jdbc.update("UPDATE sheet SET today = ?, archived = ? WHERE id = ?", Date.valueOf(sheet.today()),
179	                sheet.archived(), sheet.id());
180	    }
181	}
