 13	 * A period of a sheet: its name (unique on the sheet) and its from and to dates, both inclusive. A closed
 14	 * period keeps the due-total fixed when it was closed ({@code closedTotal}; null while open) and each person's
 15	 * due-total for it then ({@code personTotals}, by person id; empty while open), with the figure carried into it then
 16	 * ({@code personCarried}, by person id; empty while open). A soft-closed period
 17	 * ({@code softClosed}; never also {@code closed}) keeps its figures fixed the same way, but claims due by a date in it can
 18	 * still be added and changed. {@code cap} is the most OPEN or PENDING claims due by a date in it a person may have
 19	 * when another of theirs is opened (null: no cap). A {@code locked} period, locked by a steward, cannot be reopened.
 20	 */
 21	public record Period(String sheetId, String name, LocalDate from, LocalDate to, boolean closed,
 22	        BigDecimal closedTotal, Map<Long, BigDecimal> personTotals, boolean softClosed, Integer cap,
 23	        Map<Long, BigDecimal> personCarried, boolean locked) {
 24	
 25	    /** A new, open period with no cap. */
 26	    public Period(String sheetId, String name, LocalDate from, LocalDate to) {
 27	        this(sheetId, name, from, to, null);
 28	    }
 29	
 30	    /** A new, open period with this cap (null: none). */
 31	    public Period(String sheetId, String name, LocalDate from, LocalDate to, Integer cap) {
 32	        this(sheetId, name, from, to, false, null, Map.of(), false, cap, Map.of(), false);
 33	    }
 34	
 35	    /** Whether the period's figures are fixed: it is closed or soft-closed. */
 36	    public boolean fixed() {
 37	        return closed || softClosed;
 38	    }
 39	
 40	    /** Whether the period shares a day with the other. */
 41	    public boolean overlaps(Period other) {
 42	        return !from.isAfter(other.to()) && !other.from().isAfter(to);
 43	    }
 44	
 45	    /** Whether the date falls in the period, both ends included. */
 46	    public boolean contains(LocalDate date) {
 47	        return !date.isBefore(from) && !date.isAfter(to);
 48	    }
 49	
 50	    /**
 51	     * The status the claim had at the end of the period's last day, as its status log (oldest first) records it: the
 52	     * last line logged on or before it; null when it was added after. A claim with no log is taken at its status now.
 53	     */
 54	    public ClaimStatus statusAtEnd(Claim claim, List<ClaimLogLine> log) {
 55	        if (log.isEmpty()) {
 56	            return claim.status();
 57	        }
 58	        ClaimStatus status = null;
 59	        for (ClaimLogLine line : log) {
 60	            if (!line.date().isAfter(to)) {
 61	                status = line.status();
 62	            }
 63	        }
 64	        return status;
 65	    }
