 93	            return false;
 94	        }
 95	        ClaimStatus then = statusAtEnd(claim, log);
 96	        if (then == null || !then.open() || claim.deferred(today)) {
 97	            return false;
 98	        }
 99	        return !claim.status().open() || claim.bound() || !person.heldOn(claim.date(), today);
