153	/**
154	 * Closes a period, fixing its due-total as it stands now: the dues (figures plus any late charge, as they are now) of
155	 * the claims dated in it that count by their status at the period's end, added up (n/a skipped), and each person's
156	 * share of it (0.00 for a person with none), with the figure carried into it for each person: the dues of their
157	 * claims from earlier periods still open at its end (see {@link Period#carries}), plus the opening balances pasted for them into it. Used by a close by hand and by the automatic close when today changes.
158	 */
159	@Component
160	public class PeriodCloser {
161	
162	    private final ClaimRepository claims;
163	    private final ClaimLogRepository logs;
164	    private final PersonRepository people;
165	    private final PeriodRepository periods;
166	    private final RateRepository rates;
167	    private final SettingRepository settings;
168	    private final SheetRepository sheets;
169	    private final OpeningRepository openings;
170	
171	    public PeriodCloser(ClaimRepository claims, ClaimLogRepository logs, PersonRepository people,
172	            PeriodRepository periods, RateRepository rates, SettingRepository settings, SheetRepository sheets,
173	            OpeningRepository openings) {
174	        this.claims = claims;
175	        this.logs = logs;
176	        this.people = people;
177	        this.periods = periods;
178	        this.rates = rates;
179	        this.settings = settings;
180	        this.sheets = sheets;
181	        this.openings = openings;
182	    }
183	
184	    /** The same period, closed with its due-total and each person's due-total fixed as they stand now. */
185	    public Period close(Period period) {
186	        return fix(period, false);
187	    }
188	
189	    /** The same period, soft-closed with its due-total and each person's due-total fixed as they stand now. */
190	    public Period softClose(Period period) {
191	        return fix(period, true);
192	    }
193	
194	    private Period fix(Period period, boolean soft) {
195	        Map<Long, Person> byId = people.findAll(period.sheetId()).stream()
196	                .collect(Collectors.toMap(Person::id, Function.identity()));
197	        List<Rate> sheetRates = rates.findAll(period.sheetId());
198	        DatedSettings dated = settings.dated(period.sheetId());
199	        LocalDate today = sheets.today(period.sheetId());
200	        List<Claim> sheetClaims = claims.findAll(period.sheetId());
201	        Map<Long, List<ClaimLogLine>> sheetLogs = logs.findAll(period.sheetId());
202	        Rounding rounding = settings.rounding(period.sheetId(), today, sheetClaims);
203	        BigDecimal total = BigDecimal.ZERO.setScale(2);
204	        List<Period> sheetPeriods = periods.findAll(period.sheetId());
205	        Map<Long, BigDecimal> perPerson = new HashMap<>();
206	        Map<Long, BigDecimal> carried = new HashMap<>();
207	        for (Long id : byId.keySet()) {
208	            perPerson.put(id, BigDecimal.ZERO.setScale(2));
209	            carried.put(id, BigDecimal.ZERO.setScale(2));
210	        }
211	        openings.totals(period.sheetId(), period.name()).forEach((id, amount) -> {
212	            if (carried.containsKey(id)) {
213	                carried.merge(id, amount, BigDecimal::add);
214	            }
215	        });
216	        for (Claim claim : sheetClaims) {
217	            Person person = byId.get(claim.personId());
218	            if (person == null) {
219	                continue;
220	            }
221	            List<ClaimLogLine> log = sheetLogs.getOrDefault(claim.id(), List.of());
222	            boolean counts = period.counts(claim, log, person, today);
223	            boolean carries = period.carries(claim, log, person, today, sheetPeriods);
224	            if (!counts && !carries) {
225	                continue;
226	            }
227	            BigDecimal figure = claim.due(Rate.inForce(sheetRates, person.gradeOn(claim.date()), claim),
228	                    dated.floorOn(claim.date()), dated.lateCharge(today, person), rounding);
229	            if (figure == null) {
230	                continue;
231	            }
232	            if (counts) {
233	                total = total.add(figure);
234	                perPerson.merge(person.id(), figure, BigDecimal::add);
235	            }
236	            if (carries) {
237	                carried.merge(person.id(), figure, BigDecimal::add);
238	            }
239	        }
240	        return soft ? period.softClose(total, perPerson, carried) : period.close(total, perPerson, carried);
241	    }
242	}
243	package net.officefloor.hq.app.period;
244	
245	import java.util.Comparator;
246	import net.officefloor.hq.app.Audit;
247	import net.officefloor.hq.app.setting.SettingRepository;
248	import net.officefloor.hq.app.sheet.Sheet;
249	import net.officefloor.plugin.variable.Val;
250	import org.springframework.web.bind.annotation.RequestParam;
251	
252	/**
253	 * Once the sheet's new today is set, closes every open period whose to-date plus the sheet's grace days is before it
254	 * (none while the grace days are off), in order of their to-dates, as a close by hand would; each is recorded as
255	 * PERIOD_CLOSED with auto=yes.
256	 */
257	public class AutoClosePeriods {
258	    public void close(@Val Sheet sheet, PeriodRepository periods, PeriodCloser closer, SettingRepository settings,
259	            @RequestParam("user") String user, Audit audit) {
260	        Integer graceDays = settings.graceDays(sheet.id());
261	        if (graceDays == null) {
262	            return;
263	        }
264	        for (Period period : periods.findAll(sheet.id()).stream().sorted(Comparator.comparing(Period::to)).toList()) {
265	            if (period.fixed() || !period.to().plusDays(graceDays).isBefore(sheet.today())) {
266	                continue;
267	            }
268	            Period closed = closer.close(period);
269	            periods.saveClosed(closed);
270	            audit.record("PERIOD_CLOSED sheet=" + closed.sheetId() + " by=" + user + " period=" + closed.name()
271	                    + " total=" + closed.closedTotal().setScale(2).toPlainString() + " auto=yes");
272	        }
273	    }
274	}
